 "content": "def transform(grid):
    """Zero the rows and columns marked by a 2x2 zero block, preserving 2s."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    markers = []
    for r in range(h - 1):
        for c in range(w - 1):
            if all(grid[rr][cc] == 0 for rr in (r, r + 1) for cc in (c, c + 1)):
                markers.append((r, c))
    if not markers:
        return out
    rows = set()
    cols = set()
    for r, c in markers:
        rows.update((r, r + 1))
        cols.update((c, c + 1))
    for r in range(h):
        for c in range(w):
            if (r in rows or c in cols) and grid[r][c] != 2:
                out[r][c] = 0
    return out
